import{_ as t,o as a,c as n,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Pillar 4: Agentic Test-Driven Development","description":"Component of the Agentic Development Framework documentation.","frontmatter":{"type":"Agentic Development Framework","title":"Pillar 4: Agentic Test-Driven Development","description":"Component of the Agentic Development Framework documentation.","tags":["framework","internal"],"isInternal":true},"headers":[],"relativePath":"framework/pillar-4-agentic-tdd.md","filePath":"framework/pillar-4-agentic-tdd.md"}'),o={name:"framework/pillar-4-agentic-tdd.md"};function i(r,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h3 id="pillar-4-agentic-test-driven-development" tabindex="-1">Pillar 4: Agentic Test-Driven Development <a class="header-anchor" href="#pillar-4-agentic-test-driven-development" aria-label="Permalink to &quot;Pillar 4: Agentic Test-Driven Development&quot;">​</a></h3><p><strong>Purpose:</strong> Prevent AI code hallucinations from reaching production by mandating a strict write → fail → implement → pass cycle.</p><p><strong>The Four-Step Cycle:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. WRITE THE TEST  → (Playwright for E2E, Jest/Vitest for unit)</span></span>
<span class="line"><span>2. RUN THE TEST    → Watch it fail (proves the test is meaningful)</span></span>
<span class="line"><span>3. IMPLEMENT LOGIC → Write the minimum code to pass</span></span>
<span class="line"><span>4. VERIFY          → Run the test until it passes</span></span></code></pre></div><p><strong>Why This Matters for AI:</strong></p><p>Traditional TDD is a discipline choice for human developers. For AI agents, it is a <strong>safety mechanism</strong>. Without TDD, an agent can generate syntactically valid, type-safe code that is functionally incorrect — and the error may not surface until production. A failing test forces the agent to prove that its implementation actually solves the problem.</p><p><strong>E2E Testing Guardrails (Lessons Learned):</strong></p><p>The following rules were discovered through painful multi-round debugging sessions and are now codified in the <code>e2e-testing-playwright</code> skill:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Problem It Solves</th></tr></thead><tbody><tr><td>Use <code>page.locator(&#39;button&#39;, { hasText: &#39;...&#39; })</code> over <code>getByRole</code> for emoji buttons</td><td>Playwright&#39;s accessible name matching breaks on Unicode emoji characters</td></tr><tr><td>Use <code>toBeAttached()</code> instead of <code>toBeVisible()</code> for elements behind modals</td><td><code>toBeVisible()</code> fails if another DOM element overlaps the target</td></tr><tr><td>All mock Firestore docs MUST include relational foreign keys</td><td>Frontend <code>where()</code> queries return empty if the mock omits the key</td></tr><tr><td>Wait 1–3 seconds after Firestore writes before asserting UI state</td><td>React&#39;s <code>onSnapshot → setState → re-render</code> cycle needs time to settle</td></tr><tr><td>Accept downstream states in assertions (not intermediate states)</td><td>Firebase emulator backend functions execute instantly, skipping intermediate states</td></tr></tbody></table><hr>`,10)])])}const g=t(o,[["render",i]]);export{h as __pageData,g as default};
